const LEGACY_LANGUAGE_CODE_MAP = {
  jp: 'ja',
} as const

const ROSETTA_LANGUAGE_CODE_MAP = {
  ja: 'jp',
} as const

export const normalizeLanguageCode = (value?: string | null) => {
  if (typeof value !== 'string') {
    return null
  }

  const trimmed = value.trim()
  if (!trimmed) {
    return null
  }

  return LEGACY_LANGUAGE_CODE_MAP[trimmed as keyof typeof LEGACY_LANGUAGE_CODE_MAP] ?? trimmed
}

export const resolveI18nLocaleCode = (value?: string | null) => {
  const normalized = normalizeLanguageCode(value)
  if (!normalized) {
    return 'en'
  }

  return ROSETTA_LANGUAGE_CODE_MAP[normalized as keyof typeof ROSETTA_LANGUAGE_CODE_MAP] ?? normalized
}

export const isSupportedLanguageCode = (value?: string | null): value is string => {
  const normalized = normalizeLanguageCode(value)
  return !!normalized && SUPPORTED_LANGUAGES.some((language) => language.code === normalized)
}

const mergeTranslationTable = (base: Record<string, unknown>, overrides: Record<string, unknown>) => {
  const next = { ...base }

  Object.entries(overrides).forEach(([key, value]) => {
    if (
      value &&
      typeof value === 'object' &&
      !Array.isArray(value) &&
      next[key] &&
      typeof next[key] === 'object' &&
      !Array.isArray(next[key])
    ) {
      next[key] = mergeTranslationTable(
        next[key] as Record<string, unknown>,
        value as Record<string, unknown>,
      )
      return
    }

    next[key] = value
  })

  return next
}

const generatedLocaleTables = generatedOverrides?.locales ?? {}
Object.entries(generatedLocaleTables).forEach(([languageCode, table]) => {
  if (!table || typeof table !== 'object') {
    return
  }

  const localeCode = resolveI18nLocaleCode(languageCode)
  const currentTable = (i18n.table(localeCode) ?? {}) as Record<string, unknown>
  i18n.set(localeCode, mergeTranslationTable(currentTable, table as Record<string, unknown>))
})
